export class SearchClient {
  readonly #device: Device

  constructor(device: Device) {
    this.#device = device
  }

  /**
   * Returns the capabilities of the search service. The result is returned in a typed answer.
   *
   * @param request - The `GetServiceCapabilities` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetServiceCapabilitiesResponse`
   */
  getServiceCapabilities(
    request?: GetServiceCapabilitiesRequest,
    options?: CallOptions
  ): Promise<GetServiceCapabilitiesResponse> {
    return this.#device.call(GetServiceCapabilities, request, options)
  }

  /**
   * GetRecordingSummary is used to get a summary description of all recorded data. This operation is
   * mandatory to support for a device implementing the recording search service.
   *
   * @param request - The `GetRecordingSummary` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetRecordingSummaryResponse`
   */
  getRecordingSummary(
    request?: GetRecordingSummaryRequest,
    options?: CallOptions
  ): Promise<GetRecordingSummaryResponse> {
    return this.#device.call(GetRecordingSummary, request, options)
  }

  /**
   * Returns information about a single Recording specified by a RecordingToken. This operation is
   * mandatory to support for a device implementing the recording search service.
   *
   * @param request - The `GetRecordingInformation` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetRecordingInformationResponse`
   */
  getRecordingInformation(
    request: GetRecordingInformationRequest,
    options?: CallOptions
  ): Promise<GetRecordingInformationResponse> {
    return this.#device.call(GetRecordingInformation, request, options)
  }

  /**
   * Returns a set of media attributes for all tracks of the specified recordings at a specified point in
   * time. Clients using this operation shall be able to use it as a non blocking operation. A device
   * shall set the starttime and endtime of the MediaAttributes structure to equal values if calculating
   * this range would causes this operation to block. See MediaAttributes structure for more information.
   * This operation is mandatory to support for a device implementing the recording search service.
   *
   * @param request - The `GetMediaAttributes` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetMediaAttributesResponse`
   */
  getMediaAttributes(request: GetMediaAttributesRequest, options?: CallOptions): Promise<GetMediaAttributesResponse> {
    return this.#device.call(GetMediaAttributes, request, options)
  }

  /**
   * FindRecordings starts a search session, looking for recordings that matches the scope (See 20.2.4)
   * defined in the request. Results from the search are acquired using the GetRecordingSearchResults
   * request, specifying the search token returned from this request. The device shall continue searching
   * until one of the following occurs: The entire time range from StartPoint to EndPoint has been
   * searched through. The total number of matches has been found, defined by the MaxMatches parameter.
   * The session has been ended by a client EndSession request. The session has been ended because
   * KeepAliveTime since the last request related to this session has expired. The order of the results
   * is undefined, to allow the device to return results in any order they are found. This operation is
   * mandatory to support for a device implementing the recording search service.
   *
   * @param request - The `FindRecordings` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `FindRecordingsResponse`
   */
  findRecordings(request: FindRecordingsRequest, options?: CallOptions): Promise<FindRecordingsResponse> {
    return this.#device.call(FindRecordings, request, options)
  }

  /**
   * GetRecordingSearchResults acquires the results from a recording search session previously initiated
   * by a FindRecordings operation. The response shall not include results already returned in previous
   * requests for the same session. If MaxResults is specified, the response shall not contain more than
   * MaxResults results. The number of results relates to the number of recordings. For viewing
   * individual recorded data for a signal track use the FindEvents method. GetRecordingSearchResults
   * shall block until: MaxResults results are available for the response if MaxResults is specified.
   * MinResults results are available for the response if MinResults is specified. WaitTime has expired.
   * Search is completed or stopped. This operation is mandatory to support for a device implementing the
   * recording search service.
   *
   * @param request - The `GetRecordingSearchResults` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetRecordingSearchResultsResponse`
   */
  getRecordingSearchResults(
    request: GetRecordingSearchResultsRequest,
    options?: CallOptions
  ): Promise<GetRecordingSearchResultsResponse> {
    return this.#device.call(GetRecordingSearchResults, request, options)
  }

  /**
   * FindEvents starts a search session, looking for recording events (in the scope that matches the
   * search filter defined in the request. Results from the search are acquired using the
   * GetEventSearchResults request, specifying the search token returned from this request. The device
   * shall continue searching until one of the following occurs: The entire time range from StartPoint to
   * EndPoint has been searched through. The total number of matches has been found, defined by the
   * MaxMatches parameter. The session has been ended by a client EndSession request. The session has
   * been ended because KeepAliveTime since the last request related to this session has expired. Results
   * shall be ordered by time, ascending in case of forward search, or descending in case of backward
   * search. This operation is mandatory to support for a device implementing the recording search
   * service.
   *
   * @param request - The `FindEvents` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `FindEventsResponse`
   */
  findEvents(request: FindEventsRequest, options?: CallOptions): Promise<FindEventsResponse> {
    return this.#device.call(FindEvents, request, options)
  }

  /**
   * GetEventSearchResults acquires the results from a recording event search session previously
   * initiated by a FindEvents operation. The response shall not include results already returned in
   * previous requests for the same session. If MaxResults is specified, the response shall not contain
   * more than MaxResults results. GetEventSearchResults shall block until: MaxResults results are
   * available for the response if MaxResults is specified. MinResults results are available for the
   * response if MinResults is specified. WaitTime has expired. Search is completed or stopped. This
   * operation is mandatory to support for a device implementing the recording search service.
   *
   * @param request - The `GetEventSearchResults` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetEventSearchResultsResponse`
   */
  getEventSearchResults(
    request: GetEventSearchResultsRequest,
    options?: CallOptions
  ): Promise<GetEventSearchResultsResponse> {
    return this.#device.call(GetEventSearchResults, request, options)
  }

  /**
   * GetSearchState returns the current state of the specified search session. This command is deprecated
   * .
   *
   * @param request - The `GetSearchState` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `GetSearchStateResponse`
   */
  getSearchState(request: GetSearchStateRequest, options?: CallOptions): Promise<GetSearchStateResponse> {
    return this.#device.call(GetSearchState, request, options)
  }

  /**
   * EndSearch stops and ongoing search session, causing any blocking result request to return and the
   * SearchToken to become invalid. If the search was interrupted before completion, the point in time
   * that the search had reached shall be returned. If the search had not yet begun, the StartPoint shall
   * be returned. If the search was completed the original EndPoint supplied by the Find operation shall
   * be returned. When issuing EndSearch on a FindRecordings request the EndPoint is undefined and shall
   * not be used since the FindRecordings request doesn't have StartPoint/EndPoint. This operation is
   * mandatory to support for a device implementing the recording search service.
   *
   * @param request - The `EndSearch` request
   * @param options - Abort signal, timeout and addressing for this call
   * @returns The decoded `EndSearchResponse`
   */
  endSearch(request: EndSearchRequest, options?: CallOptions): Promise<EndSearchResponse> {
    return this.#device.call(EndSearch, request, options)
  }
}
